package dev.pocketengine.features.local.runtime;

import static org.junit.Assert.*;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.local.project.ProjectCommandSpec;
import dev.pocketengine.features.local.project.ProjectSources;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.json.*;
import org.junit.*;

/** The actual host JNI PTY through existing managed jobs, logs and retained lease. Not Android. */
public final class ManagedPtyJobsTest {
    private Path root,active;private ManagedProcessJobs jobs;private RuntimeInvocation invocation;private boolean expectedUnresolvedLease;private final List<ManagedProcessJobs.ProcessInputReceipt> receipts=new CopyOnWriteArrayList<>();private final AtomicBoolean released=new AtomicBoolean();
    @Before public void create()throws Exception{root=Files.createTempDirectory("c2-managed-pty-");active=Files.createDirectory(root.resolve("active"));Files.writeString(active.resolve("Main.java"),"class Main {}\n");jobs=new ManagedProcessJobs(root.toFile(),new NativeProcessSupervisor());jobs.setProcessInputSink(receipts::add);assertTrue(jobs.ptyAvailable());}
    @After public void close()throws Exception{try{if(invocation!=null)jobs.requestCancel(invocation.executionRef());if(expectedUnresolvedLease){assertThrows(IllegalStateException.class,jobs::close);assertFalse("uncertain session must retain its actual fixture lease",released.get());}else jobs.close();}finally{try(var paths=Files.walk(root)){for(Path file:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(file);}}}
    private void start(String program,int inputBudget)throws Exception {
        JSONObject source=RuntimeContractsTest.source(),payload=ProjectCommandSpec.normalize(new JSONObject().put("executable","python3").put("argv",new JSONArray().put("-u").put("-c").put(program)).put("runMode","owned_service").put("terminal","pty").put("inputByteLimit",inputBudget)).put("checkoutId",RuntimeContractsTest.CHECKOUT).put("expectedSourceDigest",ProjectSources.describe(source).getString("sourceDigest")).put("genericCommandVersion",1).put("terminalNativeContract",NativeProcessSupervisor.PTY_EXIT_RESULT_CONTRACT);
        JSONObject exact=RuntimeContractsTest.exact(source,"termux.run",payload.getJSONArray("argv")).put("intent","command").put("payload",payload).put("requestDigest",ProjectSources.digest(payload));invocation=new RuntimeInvocation(exact,RuntimeContractsTest.binding("pty-original"),source,RuntimeContractsTest.original(),()->{},new RuntimeWorkspace(active.toFile(),"project",RuntimeContractsTest.CHECKOUT));
        jobs.start(invocation,List.of(System.getProperty("a25.python"),"-u","-c",program),Map.of("PATH","/usr/bin:/bin","LANG","C.UTF-8","TERM","xterm-256color"),active.toFile(),7000,()->released.set(true));waitFor("READY");assertFalse(released.get());
    }
    private JSONObject observe()throws Exception{return jobs.query(invocation.executionRef()).json();}
    private JSONObject waitFor(String text)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);JSONObject value=null;while(System.nanoTime()<until){value=observe();if(value.optString("stdout").contains(text))return value;Thread.sleep(5);}throw new AssertionError("missing real PTY output "+text+": "+value);}
    private JSONObject input(String op,JSONObject request)throws Exception{return jobs.processInput(invocation.executionRef(),invocation.originalControl(),op,request,()->{});}
    private JSONObject finished()throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(System.nanoTime()<until){JSONObject value=observe();if(value.has("finishedAt")&&!value.optBoolean("ownedWorkerLive"))return value;Thread.sleep(5);}throw new AssertionError("original PTY did not drain");}
    @Test public void realManagedPtyLogsAndTypedDeliveryThenCanonicalEofReleaseSameLease()throws Exception {
        start("import os,sys\nprint('READY',flush=True)\nline=sys.stdin.readline()\nprint('LINE='+line.rstrip(),flush=True)\nprint('SIZE='+str(os.get_terminal_size(0)),flush=True)\nprint('REST='+repr(sys.stdin.read()),flush=True)\n",512);
        JSONObject resize=input("resize",new JSONObject().put("action","resize").put("rows",31).put("columns",99));assertEquals("delivered",resize.getString("status"));assertEquals(31,resize.getInt("rows"));JSONObject text=new JSONObject().put("action","text").put("text","same execution 😀\n");JSONObject actual=input("text",text);assertEquals("delivered",actual.getString("status"));assertEquals(ProjectCommandSpec.encode(text.getString("text")).length,actual.getInt("writtenBytes"));assertFalse(actual.getBoolean("processTerminal"));assertFalse(actual.toString().contains("same execution"));assertEquals(2,receipts.size());assertSame(invocation.originalControl(),receipts.get(1).originalControl());
        JSONObject duplicate=input("text",text);assertEquals(actual.getLong("inputSequence"),duplicate.getLong("inputSequence"));assertEquals(2,receipts.size());waitFor("LINE=same execution 😀");assertTrue(observe().getString("stdout").contains("columns=99, lines=31"));assertEquals("delivered",input("eof",new JSONObject().put("action","eof")).getString("status"));JSONObject exit=finished();assertEquals("completed",exit.getString("status"));assertEquals(0,exit.getInt("exitCode"));assertTrue(exit.getBoolean("processExited"));assertTrue(exit.getBoolean("processGroupAbsent"));assertTrue(exit.getBoolean("processSessionAbsent"));assertTrue(exit.getBoolean("resourcesReleased"));assertTrue(released.get());assertTrue(exit.getString("stdout").contains("REST=''") );assertEquals("",exit.getString("stderr"));assertTrue(exit.getBoolean("terminalOutputMerged"));assertFalse(exit.has("requestedArgv"));assertFalse(exit.has("argv"));jobs.requireCheckoutWritable(RuntimeContractsTest.CHECKOUT);
    }
    @Test public void rejectedBeforeQueueIsTypedKnownWithoutWritingOrReplayingAndBudgetRemainsBounded()throws Exception {
        start("import sys,time\nprint('READY',flush=True)\nfor line in sys.stdin: print('VALUE='+line.rstrip(),flush=True)\n",4);
        JSONObject rejected=jobs.processInput(invocation.executionRef(),invocation.originalControl(),"revoked",new JSONObject().put("action","text").put("text","NO"),()->{throw new SecurityException("controlled owner revocation before queue");});assertEquals("not_dispatched",rejected.getString("status"));assertTrue(rejected.getBoolean("nativeQueueNeverEntered"));assertEquals(0,rejected.getInt("writtenBytes"));assertEquals(1,receipts.size());assertFalse(observe().getString("stdout").contains("NO"));
        assertEquals("delivered",input("first",new JSONObject().put("action","text").put("text","ab\n")).getString("status"));waitFor("VALUE=ab");JSONObject exhausted=input("over",new JSONObject().put("action","text").put("text","xyz\n"));assertEquals("not_dispatched",exhausted.getString("status"));assertTrue(exhausted.getBoolean("nativeQueueNeverEntered"));assertEquals(3,receipts.size());assertFalse(observe().getString("stdout").contains("xyz"));RunControl foreign=new RunControl();foreign.bindHostRun("task","later",2);assertThrows(SecurityException.class,()->jobs.processInput(invocation.executionRef(),foreign,"foreign",new JSONObject().put("action","eof"),()->{}));assertEquals(3,receipts.size());jobs.requestCancel(invocation.executionRef());JSONObject exit=finished();assertTrue(exit.getBoolean("resourcesReleased"));assertTrue(released.get());
    }
    @Test public void cancellationBeforeQueuePublishesOriginalTypedNonDispatch()throws Exception {
        start("import sys\nprint('READY',flush=True)\nfor line in sys.stdin: print('VALUE='+line.rstrip(),flush=True)\n",100);
        JSONObject request=new JSONObject().put("action","text").put("text","never-enqueued\n");
        invocation.originalControl().cancel();
        JSONObject actual=input("cancelled-before-queue",request);
        assertEquals("not_dispatched",actual.getString("status"));assertTrue(actual.getBoolean("nativeQueueNeverEntered"));assertFalse(actual.getBoolean("nativeAcknowledged"));assertEquals(0,actual.getInt("inputSequence"));assertEquals(0,actual.getInt("writtenBytes"));assertFalse(actual.getBoolean("replayAllowed"));
        assertEquals(1,receipts.size());assertSame(invocation.originalControl(),receipts.get(0).originalControl());assertSame(invocation.executionRef(),receipts.get(0).execution());assertEquals("cancelled-before-queue",receipts.get(0).json().getString("inputOperationId"));assertEquals(ProjectSources.digest(request),receipts.get(0).json().getString("inputDigest"));assertFalse(actual.toString().contains("never-enqueued"));
        assertFalse(finished().getString("stdout").contains("VALUE=never-enqueued"));assertTrue(released.get());
    }
    @Test public void checkedGateFailureBeforeQueueSettlesButExistingTicketCannotBecomeNeverQueued()throws Exception {
        start("import sys\nprint('READY',flush=True)\nfor line in sys.stdin: print('VALUE='+line.rstrip(),flush=True)\n",100);
        JSONObject rejected=jobs.processInput(invocation.executionRef(),invocation.originalControl(),"checked-before-queue",new JSONObject().put("action","text").put("text","NO"),()->{throw new java.io.IOException("controlled checked gate failure before queue");});
        assertEquals("not_dispatched",rejected.getString("status"));assertTrue(rejected.getBoolean("nativeQueueNeverEntered"));assertEquals(0,rejected.getInt("writtenBytes"));assertEquals(1,receipts.size());
        JSONObject request=new JSONObject().put("action","text").put("text","one-line\n"),delivered=input("original-ticket",request);assertEquals("delivered",delivered.getString("status"));assertEquals(2,receipts.size());
        assertThrows(InterruptedException.class,()->jobs.processInput(invocation.executionRef(),invocation.originalControl(),"original-ticket",request,()->{throw new InterruptedException("controlled interruption of existing ticket observation");}));
        assertEquals("an existing queued input must not publish a second never-queued proof",2,receipts.size());assertEquals("delivered",receipts.get(1).json().getString("status"));assertFalse(receipts.get(1).json().optBoolean("nativeQueueNeverEntered"));
        assertEquals(delivered.getLong("inputSequence"),input("original-ticket",request).getLong("inputSequence"));assertEquals(2,receipts.size());waitFor("VALUE=one-line");assertFalse(observe().getString("stdout").contains("NO"));
    }
    @Test public void nativeByteAckCannotRaceAheadOfOriginalTypedHostReceiptPublication()throws Exception {
        var entered=new CountDownLatch(1);var publish=new CountDownLatch(1);jobs.setProcessInputSink(receipt->{entered.countDown();try{if(!publish.await(3,TimeUnit.SECONDS))throw new IllegalStateException("controlled host publication deadline");receipts.add(receipt);}catch(InterruptedException error){throw new IllegalStateException(error);}});
        start("import sys\nprint('READY',flush=True)\nfor line in sys.stdin: print('VALUE='+line.rstrip(),flush=True)\n",100);
        var result=new AtomicReference<JSONObject>();var failure=new AtomicReference<Throwable>();Thread caller=new Thread(()->{try{result.set(input("blocked-publication",new JSONObject().put("action","text").put("text","ordinary\n")));}catch(Throwable error){failure.set(error);}},"c2-pty-publication-fixture");caller.start();try{assertTrue(entered.await(3,TimeUnit.SECONDS));assertNull("native byte acknowledgement alone must not return before the host typed receipt",result.get());assertTrue(caller.isAlive());assertFalse(released.get());}finally{publish.countDown();caller.join(4000);}assertNull(failure.get());assertNotNull(result.get());assertEquals("delivered",result.get().getString("status"));assertEquals(1,receipts.size());waitFor("VALUE=ordinary");jobs.requestCancel(invocation.executionRef());assertTrue(finished().getBoolean("resourcesReleased"));
    }
    @Test public void observedSessionEscapeCannotReleaseActualLeaseOrClaimAllDescendantsStopped()throws Exception {
        // The child stays in the owned SID through two real native input iterations, then
        // setsid itself. The native supervisor has observed its birth; this is not a fake PID.
        String program="import os,sys,signal,time\nchild=os.fork()\nif child==0:\n while not os.path.exists('escape.now'): time.sleep(.01)\n os.setsid()\n time.sleep(60)\n os._exit(0)\ndef stop(*args):\n os.waitpid(child,0)\n sys.exit(0)\nsignal.signal(signal.SIGTERM,stop)\nprint('READY CHILD='+str(child),flush=True)\nsys.stdin.readline()\nopen('escape.now','w').close()\ntime.sleep(60)\n";
        start(program,100);String output=observe().getString("stdout");var match=java.util.regex.Pattern.compile("CHILD=(\\d+)").matcher(output);assertTrue(output,match.find());long child=Long.parseLong(match.group(1));assertTrue(ProcessHandle.of(child).isPresent());assertEquals("delivered",input("escape-resize",new JSONObject().put("action","resize").put("rows",30).put("columns",90)).getString("status"));assertEquals("delivered",input("escape-after-tracking",new JSONObject().put("action","text").put("text","escape\n")).getString("status"));JSONObject exit=finished();expectedUnresolvedLease=true;assertEquals("unknown",exit.getString("status"));assertFalse(exit.getBoolean("processSessionAbsent"));assertFalse(exit.getBoolean("resourcesReleased"));assertFalse(exit.getBoolean("allDescendantsTerminated"));assertFalse(released.get());assertFalse("the known own fixture child must actually be reaped, not left behind",ProcessHandle.of(child).map(ProcessHandle::isAlive).orElse(false));assertThrows(IllegalStateException.class,()->jobs.requireCheckoutWritable(RuntimeContractsTest.CHECKOUT));
    }
}
